import numpy as np, torch, model
net = model.load(); neg = model.negatives()
uids=list(np.array(neg['uid'])); rows=[uids.index(u) for u in (84,91,28)]
w=torch.tensor(np.load('contrast_c3_out_act_k6.npy')); b=13.6995
st={}
def hook(m,inp,out):
    k=st['k']; st['k']+=1
    if st['lo']<=k<st['hi']:
        f=(inp[0]@w+b>st['thr']).float()
        return out+f[:,None]*torch.tensor(st['cst'])
    return out
net.out.register_forward_hook(hook)
def dec(xi,c,**o):
    st.update(k=0,lo=0,hi=7,thr=0.,cst=(0.,0.)); st.update(o)
    with torch.no_grad(): a=model.decode(net,xi,c)
    a=a[0] if isinstance(a,tuple) else a
    return np.asarray(a)
rng=np.random.default_rng(5); N=2048
data=[]
for r in rows:
    xi=rng.standard_normal((N,2)).astype(np.float32); c=np.full(N,neg['c'][r],np.float32)
    a0=dec(xi,c); data.append((r,xi,c,a0,np.asarray(model.in_basin(r,a0)).astype(bool)))
base=np.mean([d[4].mean() for d in data]); print('base',round(base,3))
best=None
for thr in [0.5,1.0,1.5]:
  for lo,hi in [(0,7),(3,7),(5,8)]:
